window.addEventListener('afterprint', () => document.body.classList.remove('print-story','print-coloring'));
const BOOKS=[
{id:'kolobok',title:'Колобок',author:'Русская народная сказка',image:'/assets/covers/kolobok.jpg',source:'https://mishka-knizhka.ru/skazki-dlay-detey/russkie-narodnye-skazki/russkie-skazki-pro-zhivotnyh/kolobok/',cover:'c1',age:'3–5 лет',genre:'Народные',time:'5 минут',audio:'/assets/audio/kolobok.mp3',text:'Жили-были старик со старухой. Вот и просит старик: «Испеки, старуха, колобок». Старуха по коробу поскребла, по сусеку помела — и набралось муки горсти две. Замесила тесто, испекла колобок и положила на окошко остудить.\n\nНадоело колобку лежать, он и покатился по дорожке. Катится, катится — навстречу ему заяц. «Колобок, колобок, я тебя съем!» — сказал заяц. А колобок запел свою песенку и покатился дальше.'},
{id:'repka',title:'Репка',author:'Русская народная сказка',image:'/assets/covers/repka.jpg',source:'https://mishka-knizhka.ru/skazki-dlay-detey/russkie-narodnye-skazki/russkie-skazki-pro-zhivotnyh/repka/',cover:'c2',age:'3–5 лет',genre:'Народные',time:'3 минуты',text:'Посадил дед репку. Выросла репка большая-пребольшая. Стал дед репку из земли тянуть: тянет-потянет, вытянуть не может.\n\nПозвал дед бабку. Бабка за дедку, дедка за репку — тянут-потянут, вытянуть не могут. Позвала бабка внучку, внучка позвала Жучку, Жучка — кошку, а кошка — мышку. Потянули дружно — и вытянули репку!'},
{id:'three-pigs',title:'Три поросёнка',author:'С. Михалков',image:'/assets/covers/three-pigs.jpg',source:'https://mishka-knizhka.ru/skazki-dlay-detey/skazki-narodov-mira/tri-porosenka/',cover:'c3',age:'5–8 лет',genre:'Про животных',time:'8 минут',text:'Жили-были три поросёнка. Летом они веселились и бегали по зелёным лугам, а когда пришла осень, решили построить себе домики. Первый построил дом из соломы, второй — из веток, а третий взялся за кирпичи.\n\nОднажды к домикам пришёл голодный волк. Но крепкий кирпичный дом оказался поросятам надёжной защитой.'},
{id:'masha',title:'Маша и медведь',author:'Русская народная сказка',image:'/assets/covers/masha.jpg',source:'https://mishka-knizhka.ru/skazki-dlay-detey/russkie-narodnye-skazki/russkie-skazki-pro-zhivotnyh/masha-i-medved/',cover:'c4',age:'5–8 лет',genre:'Народные',time:'7 минут',text:'Жила-была девочка Маша. Однажды пошла она в лес с подружками да и заблудилась. Долго ходила Маша по тропинкам, пока не увидела избушку. А в той избушке жил большой медведь.\n\nМаша придумала, как вернуться к бабушке с дедушкой. Она испекла пирожки, спряталась в короб и попросила медведя отнести гостинцы в деревню.'},
{id:'sivka',title:'Сивка-Бурка',author:'Русская народная сказка',image:'/assets/covers/sivka-burka.jpg',source:'https://mishka-knizhka.ru/skazki-dlay-detey/russkie-narodnye-skazki/russkie-volshebnye-skazki/sivka-burka/',cover:'c5',age:'5–8 лет',genre:'Народные',time:'10 минут',text:'Жил-был старик, и было у него три сына. Младшего звали Иванушка. Однажды он помог волшебному коню, и тот обещал приходить на зов: «Сивка-Бурка, вещий каурка, стань передо мной, как лист перед травой!»\n\nС помощью верного друга Иванушка отправился навстречу удивительным приключениям.'},
{id:'little-red',title:'Красная Шапочка',author:'Шарль Перро',image:'/assets/covers/red-riding-hood.jpg',source:'https://mishka-knizhka.ru/skazki-dlay-detey/zarubezhnye-skazochniki/skazki-sharlya-perro/krasnaja-shapochka/',cover:'c6',age:'5–8 лет',genre:'Авторские',time:'8 минут',text:'Жила-была маленькая девочка. Бабушка подарила ей красную шапочку, и девочка так полюбила её, что всегда носила. Однажды мама попросила отнести бабушке пирожки.\n\nПо дороге через лес Красная Шапочка встретила волка. Эта история напоминает: важно слушаться взрослых и быть внимательными.'},
{id:'thumbelina',title:'Дюймовочка',author:'Г. Х. Андерсен',image:'/assets/covers/thumbelina.jpg',source:'https://mishka-knizhka.ru/skazki-dlay-detey/zarubezhnye-skazochniki/skazki-andersena/djujmovochka/',cover:'c7',age:'9–12 лет',genre:'Авторские',time:'12 минут',text:'У одной женщины не было детей. Она отправилась к доброй волшебнице и попросила помочь. Волшебница дала ей маленькое зёрнышко, из которого вырос чудесный цветок. В цветке сидела крошечная девочка.\n\nЖизнь Дюймовочки была полна встреч и приключений. Она познакомилась с полевой мышью, кротом и ласточкой, а в конце нашла новый дом и добрых друзей.'},
{id:'turnip',title:'Лисичка со скалочкой',author:'Русская народная сказка',image:'/assets/covers/fox-rolling-pin.jpg',source:'https://mishka-knizhka.ru/skazki-dlay-detey/russkie-narodnye-skazki/russkie-skazki-pro-zhivotnyh/lisichka-so-skalochkoj-russkaja-narodnaja-skazka/',cover:'c8',age:'5–8 лет',genre:'Про животных',time:'4 минуты',text:'Шла лисичка по дорожке, нашла скалочку и попросилась переночевать в избушку. Утром сказала, что скалочку съели, и попросила за неё курочку.\n\nТак лисичка хитрила в каждом новом доме, пока не встретила петушка, который её перехитрил.'},
{id:'aybolit',title:'Доктор Айболит',author:'Корней Чуковский',image:'/assets/covers/aybolit.jpg',source:'https://mishka-knizhka.ru/skazki-dlay-detey/russkie-skazochniki/skazki-chukovskogo/doktor-ajbolit-i-ego-zveri-chukovskij-k-i/',cover:'c9',age:'5–8 лет',genre:'Стихи',time:'9 минут',text:'Добрый доктор Айболит лечит зверей и всегда спешит на помощь. Однажды ему пришла телеграмма из Африки — заболели зверята. Доктор собрал чемоданчик и отправился в далёкий путь.\n\nВесёлая история о доброте, смелости и заботе о тех, кому нужна помощь.'},
{id:'moydodyr',title:'Мойдодыр',author:'Корней Чуковский',image:'/assets/covers/moidodyr.jpg',source:'https://mishka-knizhka.ru/stihi-dlya-detej/detskie-klassiki/stihi-chukovskogo/mojdodyr/',cover:'c10',age:'3–5 лет',genre:'Стихи',time:'6 минут',text:'Одеяло убежало, улетела простыня, и подушка, как лягушка, ускакала от меня. Так начинается история о мальчике, который не любил умываться.\n\nНо строгий Мойдодыр объяснил, почему важно быть чистым. Весёлое стихотворение легко читать вместе и повторять наизусть.'},
{id:'fox-crane',title:'Лиса и журавль',author:'Русская народная сказка',image:'/assets/covers/fox-and-crane.jpg',source:'https://mishka-knizhka.ru/skazki-dlay-detey/russkie-narodnye-skazki/russkie-skazki-pro-zhivotnyh/lisa-i-zhuravl/',cover:'c11',age:'3–5 лет',genre:'Народные',time:'4 минуты',text:'Подружилась лиса с журавлём и позвала его в гости. Кашу размазала по тарелке — журавлю длинным клювом неудобно. Потом журавль позвал лису и подал угощение в узком кувшине.\n\nКаждый понял, каково другому. История учит принимать гостей и заботиться о друзьях.'},
{id:'cat-house',title:'Кошкин дом',author:'Самуил Маршак',image:'/assets/covers/koshkin-dom.jpg',source:'https://mishka-knizhka.ru/skazki-dlay-detey/russkie-skazochniki/skazki-marshaka/koshkin-dom/',cover:'c12',age:'5–8 лет',genre:'Стихи',time:'8 минут',text:'Жила-была кошка-богачка. Был у неё красивый дом с резными ставнями. Однажды случилась беда, и кошке пришлось искать приют у тех, кому она раньше не помогла.\n\nТрогательная история о дружбе, отзывчивости и о том, как важно помогать близким.'}
];

