const ARTICLES=[
{id:'family-reading',title:'Как читать вместе, чтобы ребёнку было интересно',category:'Читаем вместе',age:'3–8 лет',time:'5 минут',rating:'4,9',intro:'Простые приёмы семейного чтения без спешки и обязательных норм.',body:['Выберите удобное время и предложите ребёнку самому выбрать историю. Когда у него есть возможность выбирать, чтение воспринимается как приятное совместное занятие, а не как ещё одна обязанность.','Читайте по очереди, рассматривайте иллюстрации и делайте паузы. Не обязательно дочитывать книгу за один раз: можно остановиться на интересном месте и вернуться к нему завтра.','После истории поговорите о героях. Вместо проверки «правильно ли запомнил» спросите, кто понравился и почему, или как бы ребёнок поступил на месте героя.']},
{id:'read-before-sleep',title:'Вечернее чтение: спокойный ритуал перед сном',category:'Практика',age:'3–8 лет',time:'4 минуты',rating:'4,8',intro:'Как сделать чтение уютной частью вечера без гонки за количеством страниц.',body:['Пусть вечернее чтение проходит примерно в одно и то же время и в спокойной обстановке. Достаточно десяти минут и короткой истории, которую ребёнок выбирает сам.','Уменьшите яркость света, уберите отвлекающие устройства и не превращайте чтение в экзамен. Знакомые сказки тоже подходят: повторение помогает ребёнку чувствовать себя уверенно.']},
{id:'choose-by-age',title:'Как подобрать сказку по возрасту и интересам',category:'По возрасту',age:'3–12 лет',time:'6 минут',rating:'4,9',intro:'На что смотреть кроме возрастной маркировки книги.',body:['Возрастная рекомендация помогает сузить выбор, но не заменяет интересы конкретного ребёнка. Обратите внимание на длину текста, количество героев и понятность слов.','Для начинающего читателя удобны короткие истории с повторениями. Ребёнку постарше могут понравиться загадки, несколько сюжетных линий и возможность обсудить поступки персонажей.']},
{id:'questions-after',title:'О чём поговорить после прочтения сказки',category:'Разговор о книге',age:'5–12 лет',time:'5 минут',rating:'4,7',intro:'Открытые вопросы, которые помогают обсуждать сюжет без «проверки знаний».',body:['Начните с простого: какая сцена запомнилась больше всего? Затем можно поговорить о том, что герой чувствовал и почему принял именно такое решение.','Если ребёнку трудно отвечать, предложите выбор: кто поступил смелее или какой финал ему понравился? Не поправляйте каждую деталь — важнее, чтобы разговор оставался доброжелательным.']},
{id:'first-reading',title:'Как поддержать ребёнка, который только учится читать',category:'По возрасту',age:'5–8 лет',time:'7 минут',rating:'4,8',intro:'Поддержка, короткие подходы и совместное чтение помогают без лишнего давления.',body:['Чередуйте чтение взрослого и ребёнка: одну страницу читаете вы, следующую — он. Выбирайте небольшой отрывок и завершайте занятие до того, как усталость превратится в раздражение.','Хвалите усилие и интерес, а не только скорость. Иллюстрации, предсказание продолжения и чтение по ролям делают практику разнообразнее.']},
{id:'repeat-stories',title:'Почему детям нравится перечитывать знакомые истории',category:'Развитие',age:'3–8 лет',time:'3 минуты',rating:'4,9',intro:'Повторное чтение помогает замечать знакомые детали и чувствовать уверенность.',body:['Знакомая история даёт ребёнку ощущение предсказуемости. Он уже знает, что будет дальше, и может сосредоточиться на новых словах, интонациях и подробностях иллюстраций.','Если ребёнок снова просит одну и ту же сказку, можно принять этот выбор и время от времени предлагать похожую историю.']}
];
const toast=document.getElementById('toast');function notify(msg){if(!toast)return;toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}const menuBtn=document.getElementById('menuBtn'),nav=document.getElementById('nav'),navScrim=document.getElementById('navScrim');function closeMenu(){nav?.classList.remove('open');document.body.classList.remove('menu-open');menuBtn?.setAttribute('aria-expanded','false');menuBtn?.setAttribute('aria-label','Открыть меню');if(menuBtn)menuBtn.replaceChildren(icon('menu'))}menuBtn?.addEventListener('click',()=>{const open=nav.classList.toggle('open');document.body.classList.toggle('menu-open',open);menuBtn.setAttribute('aria-expanded',String(open));menuBtn.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');menuBtn.replaceChildren(icon(open?'close':'menu'))});navScrim?.addEventListener('click',closeMenu);document.querySelector('[data-menu-close]')?.addEventListener('click',closeMenu);nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});document.getElementById('toTop')?.addEventListener('click',()=>scrollTo({top:0,behavior:'smooth'}));document.getElementById('modalClose')?.addEventListener('click',()=>document.getElementById('modal')?.classList.remove('open'));document.getElementById('modal')?.addEventListener('click',e=>{if(e.target.id==='modal')e.currentTarget.classList.remove('open')});
function setupBookFilters(){const cards=[...document.querySelectorAll('.page-wrap #catalogGrid .book-card, .page-wrap .catalog-grid#catalogGrid .book-card')],genre=document.querySelector('input[name="taleGenre"]:checked')?.value||params.get('genre')||'Все',age=document.querySelector('input[name="taleAge"]:checked')?.value||params.get('age')||'Все',query=(params.get('q')||'').toLocaleLowerCase('ru');let shown=cards.filter(card=>(genre==='Все'||card.dataset.genre===genre)&&(age==='Все'||card.dataset.age===age)&&(!query||card.dataset.search.includes(query)));const sort=document.getElementById('sort');if(sort?.value==='az')shown.sort((a,b)=>a.dataset.search.localeCompare(b.dataset.search,'ru'));if(sort?.value==='time')shown.sort((a,b)=>parseInt(BOOKS.find(book=>book.id===a.dataset.bookId).time)-parseInt(BOOKS.find(book=>book.id===b.dataset.bookId).time));cards.forEach(card=>card.hidden=!shown.includes(card));const count=document.getElementById('countLabel');if(count)count.textContent='Найдено '+shown.length+' '+(shown.length===1?'сказка':'сказок');}
if(page==='tales'){const genreFromUrl=params.get('genre')||'Все',ageFromUrl=params.get('age')||'Все';const genreInput=[...document.querySelectorAll('input[name="taleGenre"]')].find(input=>input.value===genreFromUrl),ageInput=[...document.querySelectorAll('input[name="taleAge"]')].find(input=>input.value===ageFromUrl);if(genreInput)genreInput.checked=true;if(ageInput)ageInput.checked=true;setupBookFilters();document.querySelectorAll('input[name="taleGenre"],input[name="taleAge"]').forEach(input=>input.addEventListener('change',setupBookFilters));document.querySelector('[data-reset]')?.addEventListener('click',()=>{[...document.querySelectorAll('input[name="taleGenre"]')].find(input=>input.value==='Все').checked=true;[...document.querySelectorAll('input[name="taleAge"]')].find(input=>input.value==='Все').checked=true;document.getElementById('sort').value='popular';params.delete('genre');params.delete('age');setupBookFilters()});document.getElementById('sort')?.addEventListener('change',setupBookFilters)}
if(page==='activities')document.querySelectorAll('[data-riddle]').forEach(x=>x.onclick=()=>{let res=document.getElementById('riddleResult');res.hidden=false;res.textContent=x.dataset.riddle==='1'?'Верно! Пчёлы строят из воска улей.':'Попробуй ещё раз — подумай, кто строит домики из воска.'});
if(page==='quiz'){let b=BOOKS.find(x=>x.id===params.get('id'))||BOOKS[0],step=0,score=0;let questions=[['Кто автор этой истории?',[b.author,'Александр Пушкин','Корней Чуковский'],0],['Кому подошла бы эта история?',['Маленькому читателю','Никому','Только взрослым'],0],['Что можно обсудить после чтения?',['Поступки героев','Только длину книги','Ничего'],0]];function showQ(){let q=questions[step];document.getElementById('quizQuestion').textContent=`Вопрос ${step+1} из ${questions.length}. ${q[0]}`;document.getElementById('quizProgress').style.width=(step/questions.length*100)+'%';const answerBox=document.getElementById('quizAnswers');answerBox.replaceChildren();q[1].forEach((label,index)=>{const option=document.createElement('button');option.className='quiz-option';option.textContent=label;option.addEventListener('click',()=>{if(index===q[2])score++;step++;if(step<questions.length)showQ();else{document.getElementById('quizProgress').style.width='100%';document.getElementById('quizQuestion').textContent='Готово!';answerBox.replaceChildren();let r=document.getElementById('quizResult');r.hidden=false;r.textContent=`Ваш результат: ${score} из ${questions.length}. Спасибо за игру!`;recordHistory('Прошёл викторину',`Викторина по сказке «${b.title}» · ${score}/${questions.length}`,`quiz.html?id=${b.id}`)}});answerBox.append(option)})}showQ()}
if(page==='workshop'){const form=document.getElementById('storyForm'),result=document.getElementById('draftResult');form.onsubmit=e=>{e.preventDefault();const title=document.getElementById('storyTitle').value.trim(),hero=document.getElementById('storyHero').value.trim(),place=document.getElementById('storyPlace').value,story=document.getElementById('storyText').value.trim();result.replaceChildren();result.hidden=false;result.className='story-preview';const heading=document.createElement('h3'),byline=document.createElement('p'),copy=document.createElement('p');heading.textContent=title;byline.textContent=hero+' · '+place;copy.textContent=story;result.append(heading,byline,copy);result.scrollIntoView({behavior:'smooth',block:'nearest'})}}
if(page==='search'){const input=document.getElementById('pageSearch'),cards=[...document.querySelectorAll('#searchGrid .book-card')],buttons=[...document.querySelectorAll('[data-search-type]')],countLabel=document.getElementById('searchCount');let type='Все';const empty=document.createElement('p');empty.className='empty';empty.textContent='По этому фильтру пока нет материалов. Выберите другую категорию.';empty.hidden=true;document.getElementById('searchGrid')?.append(empty);if(input){input.value=params.get('q')||'';const filter=()=>{let count=0;cards.forEach(card=>{const isAudio=!!card.querySelector('.audio-play'),isPoem=card.dataset.itemType==='poem';const typeMatches=type==='Все'||type==='Сказки'||(type==='Аудио'&&isAudio)||(type==='Стихи'&&isPoem)||(type==='Рассказы'&&!isPoem&&card.dataset.search.includes('рассказ'));card.hidden=!(typeMatches&&card.dataset.search.includes(input.value.toLocaleLowerCase('ru')));if(!card.hidden)count++});empty.hidden=count>0;if(countLabel)countLabel.textContent=`Найдено материалов: ${count}`;buttons.forEach(button=>{const on=button.dataset.searchType===type;button.classList.toggle('active',on);button.setAttribute('aria-pressed',String(on))})};input.addEventListener('input',filter);buttons.forEach(button=>button.addEventListener('click',()=>{type=button.dataset.searchType;filter()}));filter()}}
