  list.addEventListener('keydown',event=>{const active=options.indexOf(document.activeElement);if(event.key==='Escape'){close();button.focus();return}if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();options[(active+(event.key==='ArrowDown'?1:-1)+options.length)%options.length]?.focus()}if(event.key==='Home'){event.preventDefault();options[0]?.focus()}if(event.key==='End'){event.preventDefault();options.at(-1)?.focus()}});
