  function makePng(callback){const result=document.createElement('canvas');result.width=outline.naturalWidth;result.height=outline.naturalHeight;const resultContext=result.getContext('2d');resultContext.fillStyle='#fff';resultContext.fillRect(0,0,result.width,result.height);resultContext.drawImage(outline,0,0);resultContext.drawImage(canvas,0,0);result.toBlob(callback,'image/png')}
